// ===== D2: JSON Schemas (strict — additionalProperties: false everywhere) =====
// Set once per request run as collection variables; parsed back out in each Tests tab.

const pageableSchema = {
  type: "object",
  properties: {
    pageNumber: { type: "integer" },
    pageSize: { type: "integer" },
    sort: {
      type: "object",
      properties: {
        empty: { type: "boolean" },
        sorted: { type: "boolean" },
        unsorted: { type: "boolean" }
      },
      required: ["empty", "sorted", "unsorted"],
      additionalProperties: false
    },
    offset: { type: "integer" },
    paged: { type: "boolean" },
    unpaged: { type: "boolean" }
  },
  required: ["pageNumber", "pageSize", "sort", "offset", "paged", "unpaged"],
  additionalProperties: false
};

const sortSchema = {
  type: "object",
  properties: {
    empty: { type: "boolean" },
    sorted: { type: "boolean" },
    unsorted: { type: "boolean" }
  },
  required: ["empty", "sorted", "unsorted"],
  additionalProperties: false
};

// ---- Air Pollution ----
const apReadingSchema = {
  type: "object",
  properties: {
    id: { type: "string" },
    location: { type: "string" },
    timestamp: { type: "string" },
    pm2_5: { type: "number" },
    pm10: { type: "number" },
    co: { type: "number" },
    no2: { type: "number" },
    so2: { type: "number" },
    ozone: { type: "number" },
    pollutionLevel: { type: "string", enum: ["GOOD", "MODERATE", "UNHEALTHY", "VERY_UNHEALTHY", "HAZARDOUS"] }
  },
  required: ["id", "location", "timestamp", "pm2_5", "pm10", "co", "no2", "so2", "ozone", "pollutionLevel"],
  additionalProperties: false
};

const apPageSchema = {
  type: "object",
  properties: {
    content: { type: "array", items: apReadingSchema },
    pageable: pageableSchema,
    totalElements: { type: "integer" },
    totalPages: { type: "integer" },
    last: { type: "boolean" },
    size: { type: "integer" },
    number: { type: "integer" },
    sort: sortSchema,
    first: { type: "boolean" },
    numberOfElements: { type: "integer" },
    empty: { type: "boolean" }
  },
  required: ["content", "pageable", "totalElements", "totalPages", "last", "size", "number", "sort", "first", "numberOfElements", "empty"],
  additionalProperties: false
};

const apStatsSchema = {
  type: "object",
  properties: {
    from: { type: ["string", "null"] },
    to: { type: ["string", "null"] },
    location: { type: ["string", "null"] },
    totalReadings: { type: "integer" },
    avgCo: { type: ["number", "null"] },
    avgOzone: { type: ["number", "null"] },
    maxCo: { type: ["number", "null"] },
    minCo: { type: ["number", "null"] },
    maxOzone: { type: ["number", "null"] },
    minOzone: { type: ["number", "null"] },
    alertsTriggered: { type: "integer" },
    pollutionLevelDistribution: { type: "object" },
    dailyAverages: {
      type: "array",
      items: {
        type: "object",
        properties: {
          date: { type: "string" },
          avgCo: { type: ["number", "null"] },
          avgOzone: { type: ["number", "null"] }
        },
        required: ["date", "avgCo", "avgOzone"],
        additionalProperties: false
      }
    }
  },
  required: ["from", "to", "location", "totalReadings", "avgCo", "avgOzone", "maxCo", "minCo", "maxOzone", "minOzone", "alertsTriggered", "pollutionLevelDistribution", "dailyAverages"],
  additionalProperties: false
};

